describe("RepositoryWorktrees", () => {
  it("refreshes once for an external path and admits a sibling worktree", async () => {
    const reads: string[] = [];
    const worktrees = new RepositoryWorktrees("C:/Repos/MindLeak", async (workspace) => {
      reads.push(workspace);
      return ["C:/Repos/MindLeak", "C:/Repos/MindLeak-sibling"];
    });

    await expect(worktrees.contains("C:/Repos/MindLeak-sibling/src/extension.ts")).resolves.toBe(
      true
    );
    await expect(worktrees.contains("C:/Repos/MindLeak-sibling/src/util.ts")).resolves.toBe(true);

    expect(reads).toStrictEqual(["C:/Repos/MindLeak"]);
  });

  it("keeps the workspace as the only root when worktree discovery is empty", async () => {
    const worktrees = new RepositoryWorktrees("C:/Repos/MindLeak", async () => []);

    await expect(worktrees.contains("C:/Temp/notes.ts")).resolves.toBe(false);
    await expect(worktrees.contains("C:/Repos/MindLeak/src/extension.ts")).resolves.toBe(true);
  });
});
